def find_score_distribution(n, m):
    if m == 0:
        return list(range(1, n + 1))

    # Check if it's possible to have m triples
    if m > n * (n - 1) // 2:
        return -1

    # Start with the simplest increasing sequence
    scores = list(range(1, n + 1))

    # Try to adjust the scores to get exactly m triples
    current_triples = 0
    for i in range(n - 2, -1, -1):
        while current_triples < m:
            scores[i] += 1
            new_triples = 0
            for j in range(i + 1, n):
                if scores[j] - scores[i] in scores[:j]:
                    new_triples += 1
            if new_triples > m - current_triples:
                scores[i] -= 1
                break
            current_triples = new_triples

    if current_triples != m:
        return -1

    return scores

